-- GENERATED by `wfj generate` from data/gossip/gossip-10.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["100b0a6cbcdf7307"] = { "Hai lottato duramente per invadere il regno del mietitore.", "." },
  ["100d16a6b0cc37df"] = { "Pausa, uomini! Mezz'ora e poi di nuovo al lavoro.", "." },
  ["100ed1ade3a0ae1d"] = { "Mi fido di pochissimi della tua specie, {name}. Ma sento che mi sei <amico/amica>.", "." },
  ["1013fd3dcf2b76b0"] = { "%s grida aiuto.", "." },
  ["1022846a66423d8b"] = { "So molte cose, <straniero/straniera>, ma le tue conoscenze rivaleggiano con le mie. Si dice che gli incantatori che vogliono affinare ancora le proprie abilità si rechino alla ⟦Tower of Azora=Torre di Azora⟧, dove risiede una specialista di nome ⟦Kitta Firewind=Kitta Bruciavento⟧.", "." },
  ["102ef9654712a7b8"] = { "Ma non può essere giusto. Dove ho messo quell'altro libro?", "." },
  ["103afe64a10c7a3c"] = { "A metà strada...", "." },
  ["103d52f1ba12f1e6"] = { "Il nostro lavoro è finito. Ora aspettiamo che l'⟦Alliance=Alleanza⟧ finisca il suo, prima di spedire tutto a ⟦Silithus=Silitus⟧.", "." },
  ["1040f379d4650fa6"] = { "L'arte degli inventori fa per te, eh? Di sicuro vorrai andare da ⟦Springspindle Fizzlegear=Frizzaruota⟧ a Tinker Town.\n\nVai a est dai cancelli di ⟦Ironforge=Forgiardente⟧, oppure segui il rumore delle esplosioni.", "." },
  ["10416c786893506c"] = { "Och, fu un giorno triste quando mi resi conto della mia ossessione. Mi svegliai e mi ritrovai a conciare pelli prima ancora del mio primo boccale di birra. Neanche un dopo-sbornia come si deve! Lo capii allora... sì, lo capii!... come sarebbero andate le cose.", "." },
  ["10417f8f95d4b43c"] = { "Lysheana può darti i documenti adatti: risiede nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nella parte nord-orientale di Darnassus. Che la tua confraternita porti gloria agli elfi della notte!", "." },
  ["104839d3e43131f2"] = { "PER KALIMDOR!", "." },
  ["1048c6c662c1f059"] = { "Vuoi imparare ad accendere un fuoco da campo? Allora faresti meglio a far visita a Malygen nell'⟦Cenarion Enclave=Enclave Cenariana⟧, prima di dare fuoco a tutta Teldrassil.", "." },
  ["10495944ccaac0e9"] = { "⟦Tower Point=Torre Granguardia⟧ è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ la distruggerà!", "." },
  ["105395306e4ab601"] = { "Salute, {race}! Sono il tenente Haggerdin, l'ufficiale incaricato del reclutamento per la ⟦Stormpike Guard=Guardia dei Piccatonante⟧.\n\nMan mano che acquisirai prestigio e fama tra i Piccatonante, torna da me e vedrò di migliorare la tua insegna. Inoltre, se dovessi mai perderla, posso fornirtene una nuova.", "." },
  ["105d37cd38ecf9f9"] = { "Intrusi! Invasori! L'Occhio Onniveggente è stato rubato! Quel cane miserabile di {name} ce l'ha in suo possesso!", "." },
  ["105f3b2889222d71"] = { "alle armi, ragazzi!", "." },
  ["1066493e7224ec63"] = { "La ⟦Thorium Brotherhood=Fratellanza del Torio⟧ possiede le conoscenze necessarie per forgiare le sacre armi e armature del Signore del Fuoco, ma ci mancano le braccia per procurarci i materiali necessari.\n\nIo, ⟦Lokhtos Darkbargainer=Lokhtos Pattoscuro⟧, ho ricevuto dalla Fratellanza il potere di scambiare le ricette più pregiate con i materiali raccolti nel ⟦Molten Core=Nucleo Ardente⟧.\n\nFai la tua offerta, {race}.", "." },
  ["106b63ee1260a596"] = { "La teoria è che ti distruggiamo completamente con un'enorme esplosione ovunque ti trovi, mandiamo quelle particelle attraverso uno squarcio dimensionale e poi ti re-implodiamo qui alla macchina. Trasporto istantaneo! Magari non funzionerà SEMPRE, ma che razza di ingegnere goblin sei! Se la sopravvivenza fosse la tua prima priorità, non potresti mai essere un vero esperto di ⟦Goblin Engineer=Ingegneria dei Goblin⟧!\nEcco la ricetta che ti serve per creare lo Squarciatore Dimensionale e provarlo!", "." },
  ["1077afa110cb865c"] = { "Salve! Ho le pelli migliori da questa parte di ⟦Stormwind=Roccavento⟧. Ti interessa?", "." },
  ["10828a333e7604cb"] = { "Maestà, fuggi finché puoi. Lei non è ciò che credi...", "." },
  ["10897850618475fe"] = { "Tutto il pesce e tutto il resto è in viaggio verso ⟦Silithus=Silitus⟧, e dovrebbe arrivare in meno di $2113w giorni. Dopo, qualcuno dovrà suonare quel gong con lo Scettro delle Sabbie Mutevoli per dare inizio alla guerra.", "." },
  ["108c3abc70bc8cfa"] = { "Se vuoi la chiave, dovrai prendermi!", "." },
  ["109730a11b49ee5b"] = { "James Van Brunt, nel ⟦War Quarter=Quartiere della Guerra⟧, sull'anello interno.", "." },
  ["10974354a52706e9"] = { "Mmm, capisco. Molto bene, {class}. I Windshaper forniranno aiuto. Per favore, informa Valennia che può contare su di noi in questa battaglia.\r\n\n<Ayessa abbassa la voce con tono minaccioso.> \r\n\nNon scambiare la nostra collaborazione per una qualche forma di perdono. Ai Windshaper devi del sangue, e un giorno lo riscuoteremo.", "." },
  ["10978d0669ca8db1"] = { "Quando prepari il pasto del drago, assicurati di torturare il prigioniero davanti al drago. Risponde bene all'intrattenimento prima dei pasti.", "." },
  ["109c9b65c751fc35"] = { "Sei qui per farti istruire nell'arte di preparare pozioni? Ti sbagliavi se pensavi che ti avrei concesso un simile privilegio senza che te lo fossi guadagnato. Vattene, e non tornare da me finché non avrai più abilità.", "." },
  ["109ded22d9d2a5db"] = { "La prossima volta, porta più amici!", "." },
  ["10a3d085bc51a7a8"] = { "Luridi codardi dei Lupi Bianchi! Se volete combattere, dovrete venire da me!", "." },
  ["10acb4364f368b1f"] = { "Il corpo della sentinella dei Guardiani della Notte che giace davanti a te è coperto di squarci e tagli profondi. È evidente che l'uomo è stato sbranato da una grossa bestia.\n\nNoti che il cadavere stringe in mano una torcia spenta. Ti chini e la sfili dalle sue dita irrigidite. Potrebbe esserti utile nei tuoi viaggi per ⟦Duskwood=Boscovespro⟧ e oltre, per rivelare ciò che l'oscurità nasconde.", "." },
  ["10af33a9afbe5ed0"] = { "Dubito che la fortuna ti assisterà ancora la prossima volta che incontrerai i miei fratelli.", "." },
  ["10b8afc45599a8e0"] = { "Presto, {name}. Te lo prometto. La tonaca sarà più che adeguata alle tue esigenze e di certo ti darà un vantaggio sui tuoi avversari.", "." },
  ["10be644418c73418"] = { "Bene bene! Sei nel posto giusto per imparare l'Estrazione, <ragazzo/ragazza>! ⟦Geofram Bouldertoe=Geofram Granditone⟧ in persona risiede alla Deepmountain Mining Guild. Non potresti chiedere un istruttore migliore di lui.", "." },
  ["10c017e5a06b5f85"] = { "Ah, di nuovo vuoto!", "." },
  ["10c243e35fcd5b02"] = { "Voi topi di terraferma siete più tosti di quanto pensassi! Dovrò improvvisare!", "." },
  ["10c60fb71e341493"] = { "La Banca di Orgrimmar è nella ⟦Valley of Strength=Valle della Forza⟧. Cercala a nord dell'ingresso principale della città.", "." },
  ["10cde9b862a7740c"] = { "Che tipi di professioni ci sono?", "." },
  ["10d906ec14a22149"] = { "Bene!\n\nIl totem che creerò per te è più di un simbolo del tuo rango tra gli {class}: ha capacità che vanno oltre. Uno degli usi del totem è come catalizzatore per gli incantesimi. Quegli incantesimi sono legati alla terra e, man mano che acquisirai sempre più saggezza, altre capacità della terra ti diventeranno accessibili.\n\nGli istruttori sapranno quando sarai <pronto/pronta> per una conoscenza superiore.\n\nMa per ora, prendi questo totem della terra...", "." },
  ["10e039fd0e9c07dd"] = { "Vince il Rosso! Congratulazioni, Rosso!", "." },
  ["10e80f7b5e5786dc"] = { "Erbe, erbe, mmm, vediamo un po'. Ah sì, eccolo. Finora abbiamo raccolto $2047w su $2048w di stranglekelp, $2053w su $2055w di Fiore di Loto Purpureo e $2057w su $2058w di Lacrima di Arthas necessari.", "." },
  ["10ee4349715f7eb1"] = { "Capitano, eccoli! Arrivano i naga!", "." },
})
